<script setup lang="ts">
import {onMounted,ref} from 'vue';import {api,getUser} from '../api';
const tables=ref<any[]>([]),tableId=ref(''),date=ref(''),time=ref('19:00'),guests=ref(2),comment=ref(''),message=ref(''),error=ref('');
onMounted(async()=>{try{tables.value=(await api.get('/tables')).data}catch{error.value='Не удалось загрузить столики'}});
async function submit(){message.value = ''; error.value = ''; const user = getUser();if(!user){error.value = 'Сначала войдите в аккаунт или зарегистрируйтесь в верхней части страницы';return;}if(user.role !== 'CLIENT'){error.value = 'Бронирование доступно только клиентам'; return;}try{const start = new Date(`${date.value}T${time.value}:00`);const end=new Date(start.getTime()+2*60*60*1000);await api.post('/reservations',{tableId:Number(tableId.value),startAt:start.toISOString(),endAt:end.toISOString(),guests:Number(guests.value),comment:comment.value});message.value='Заявка на бронирование создана! Статус можно посмотреть в личном кабинете.';}catch(e:any){error.value=e.response?.data?.message||'Ошибка бронирования';}}
</script>
<template><section class="page"><p class="eyebrow">ОНЛАЙН-БРОНИРОВАНИЕ</p><h1>Забронировать столик</h1><p class="muted">Выберите дату, время и количество гостей. Продолжительность брони — 2 часа.</p><form class="panel formgrid" @submit.prevent="submit"><label>Столик<select v-model="tableId" required><option value="" disabled>Выберите столик</option><option v-for="t in tables" :value="t.id">Столик №{{t.number}} · {{t.seats}} мест</option></select></label><label>Дата<input v-model="date" type="date" :min="new Date().toISOString().slice(0,10)" required></label><label>Время<input v-model="time" type="time" min="10:00" max="22:00" required></label><label>Количество гостей<input v-model.number="guests" type="number" min="1" max="12" required></label><label class="full">Комментарий<textarea v-model="comment" placeholder="Пожелания к бронированию"></textarea></label><button class="full">Отправить заявку</button><p class="success full" v-if="message">{{message}}</p><p class="error full" v-if="error">{{error}}</p></form></section></template>
